#!/bin/bash
# ============================================================
# Lib/build_dynamic — 动态库 FFI 绑定生成器
#
# 从用户 C 源码编译 .dylib/.so/.dll，调用 GenDyn 工具
# 自动生成 C 胶水代码 + VML 封装 + 22 语言 FFI 头文件。
#
# 用法:
#   ./build_dynamic myui.c                    # 编译+生成所有 FFI 绑定
#   ./build_dynamic myui.c -o libgfx          # 指定输出库名
#   ./build_dynamic myui.c --lang-only        # 仅生成语言头文件
#   ./build_dynamic myui.h -l libmyui.dylib   # 从已有头文件+动态库生成
#
# 示例 (myui.c):
#   int setpoint(int x, int y, int co) { return 0; }
#   void clear_screen(int color) { }
#
# 生成文件 (由 GenDyn v2 生成):
#   Lib/dynamic/<libname>.vml                  — VML FFI 封装
#   Lib/<lang>/ext/lib<libname>.<ext>          — 22 语言绑定
#
# 相关工具:
#   GenDyn (tools/GenDyn) — 外部动态库 FFI 绑定生成
# ============================================================
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

GREEN='\033[0;32m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
NC='\033[0m'
info()  { echo -e "${YELLOW}[..]${NC} $1" >&2; }
pass()  { echo -e "${GREEN}[OK]${NC} $1" >&2; }
fail()  { echo -e "${RED}[!!]${NC} $1" >&2; }

# 自动检测工具: tools/ → tools/bin/ → 源码编译发布到 tools/bin/
resolve_tool() {
    local name="$1" proj="$2"
    # 1) tools/<name> (发布包)
    if [ -f "$SCRIPT_DIR/../tools/$name" ] && [ -x "$SCRIPT_DIR/../tools/$name" ]; then
        echo "$SCRIPT_DIR/../tools/$name"
        return
    elif [ -f "$SCRIPT_DIR/../tools/$name.exe" ]; then
        echo "$SCRIPT_DIR/../tools/$name.exe"
        return
    fi
    # 2) tools/bin/<name> (上次源码编译发布)
    local asm_name=""
    asm_name="$(basename "$proj")"
    if [ -f "$SCRIPT_DIR/../tools/bin/$name" ] && [ -x "$SCRIPT_DIR/../tools/bin/$name" ]; then
        echo "$SCRIPT_DIR/../tools/bin/$name"
        return
    elif [ -f "$SCRIPT_DIR/../tools/bin/$name.exe" ]; then
        echo "$SCRIPT_DIR/../tools/bin/$name.exe"
        return
    elif [ -f "$SCRIPT_DIR/../tools/bin/$asm_name" ] && [ -x "$SCRIPT_DIR/../tools/bin/$asm_name" ]; then
        echo "$SCRIPT_DIR/../tools/bin/$asm_name"
        return
    elif [ -f "$SCRIPT_DIR/../tools/bin/$asm_name.exe" ]; then
        echo "$SCRIPT_DIR/../tools/bin/$asm_name.exe"
        return
    fi
    # 3) 有源码 → dotnet publish 到 tools/bin/，下次直接使用
    if [ -d "$PROJECT_ROOT/$proj" ]; then
        local tools_bin="$SCRIPT_DIR/../tools/bin"
        mkdir -p "$tools_bin"
        info "首次使用，正在编译发布 ${proj} → tools/bin/ ..."
        dotnet publish "$PROJECT_ROOT/$proj" -c Release -o "$tools_bin" >&2 || {
            fail "编译发布失败"
            echo ""
            return
        }
        pass "发布完成"
        local found=""
        local asm_name=""
        asm_name="$(basename "$proj")"
        for candidate in "$tools_bin/$name" "$tools_bin/$name.exe" "$tools_bin/$asm_name" "$tools_bin/$asm_name.exe"; do
            if [ -f "$candidate" ] && [ -x "$candidate" ]; then
                found="$candidate"; break
            elif [ -f "$candidate" ] && [[ "$candidate" == *.exe ]]; then
                found="$candidate"; break
            fi
        done
        if [ -z "$found" ]; then
            fail "找不到编译产物: $tools_bin/$name 或 $tools_bin/$asm_name"
        fi
        echo "${found:-}"
    else
        echo ""
    fi
}

IMPORT_DYNAMIC="$(resolve_tool "gendyn" "tools/GenDyn")"
[ -z "$IMPORT_DYNAMIC" ] && { echo "错误: 找不到 gendyn (发布目录或源码项目)"; exit 1; }

# ============================================================
# 从 C 源码提取函数声明为头文件
# ============================================================
extract_header() {
    local cfile="$1" header="$2"
    {
        echo "/* Auto-generated by build_dynamic — extracted from ${cfile} */"
        grep -n '^\s*\(void\|int\|char\|short\|long\|float\|double\|unsigned\)\s\+[_*a-zA-Z][_a-zA-Z0-9]*\s*(' "$cfile" |
            grep -v '^\s*//' |
            sed 's/^[0-9]*://; s/\s*{.*//; s/^\s*//; s/;*$/;/' |
            while IFS= read -r line; do
                local name
                name="$(echo "$line" | sed 's/.*\s\(\w\+\)(.*/\1/')"
                case "$name" in if|while|for|return|switch|case|sizeof|main) continue ;; esac
                echo "extern $line"
            done
        echo ""
    } > "$header"
}

# ============================================================
# 平台检测
# ============================================================
detect_platform() {
    case "$(uname -s)" in
        Darwin)  echo "macos" ;;
        Linux)   echo "linux" ;;
        MINGW*|MSYS*|CYGWIN*) echo "windows" ;;
        *)       echo "unknown" ;;
    esac
}

# ============================================================
# 主流程
# ============================================================

main() {
    cd "$SCRIPT_DIR"
    local infile="" libname="" dylib_path="" lang_only=false

    while [ $# -gt 0 ]; do
        case "$1" in
            -o) libname="$2"; shift 2 ;;
            -l) dylib_path="$2"; shift 2 ;;
            --lang-only) lang_only=true; shift ;;
            -h|--help)
                echo "build_dynamic — 用户 C 源码 → 动态库 + 16 语言 FFI 绑定"
                echo "用法: build_dynamic <file.c|file.h> [-o libname] [-l dylib] [--lang-only]"
                echo ""
                echo "内部调用 GenDyn 工具生成:"
                echo "  C 胶水代码 (<lib>_lib.c) + VML 封装 (<lib>_lib.vml) + 16 语言头文件"
                echo ""
                echo "相关工具:"
                echo "  GenDyn   外部动态库 FFI 绑定生成 (本脚本的后端)"
                echo "  GenLib         VML 标准共享库管理"
                exit 0
                ;;
            *) infile="$1"; shift ;;
        esac
    done

    [ -z "$infile" ] && { fail "用法: build_dynamic <file.c|file.h> [-o libname] [-l dylib]"; exit 1; }
    [ ! -f "$infile" ] && { fail "文件不存在: $infile"; exit 1; }

    local ext="${infile##*.}"
    [ -z "$libname" ] && libname="$(basename "$infile" ".$ext")"

    local platform
    platform="$(detect_platform)"
    info "平台: $platform"

    # 情况1: 输入是 .c 文件 → 编译为动态库 + 提取头文件 → GenDyn
    if [ "$ext" = "c" ]; then
        local header="/tmp/build_dynamic_${libname}.h"
        info "提取函数声明: ${infile} → ${header}"
        extract_header "$infile" "$header"

        local dylib=""
        case "$platform" in
            macos) dylib="lib${libname}.dylib" ;;
            linux) dylib="lib${libname}.so" ;;
            windows) dylib="${libname}.dll" ;;
            *) fail "不支持的平台"; exit 1 ;;
        esac

        info "编译动态库: ${infile} → ${dylib}"
        case "$platform" in
            macos)
                cc -shared -fPIC -o "$dylib" "$infile" 2>&1 || {
                    fail "动态库编译失败 (需要 cc/gcc)"
                    fail "请确保已安装 Xcode Command Line Tools: xcode-select --install"
                    exit 1
                } ;;
            linux)
                cc -shared -fPIC -o "$dylib" "$infile" 2>&1 || {
                    fail "动态库编译失败 (需要 cc/gcc)"
                    exit 1
                } ;;
            windows)
                cl /nologo /O2 /MD /LD /Fe:"$dylib" "$infile" 2>&1 || {
                    fail "动态库编译失败 (需要 MSVC cl.exe)"
                    exit 1
                } ;;
        esac
        pass "${dylib}"

        info "调用 GenDyn v2 生成 FFI 绑定..."
        if $lang_only; then
            $IMPORT_DYNAMIC -g -n "$libname" -H "$header" -r "$PROJECT_ROOT" 2>&1 || {
                fail "GenDyn 执行失败"
                exit 1
            }
        else
            $IMPORT_DYNAMIC -A -n "$libname" -H "$header" -r "$PROJECT_ROOT" 2>&1 || {
                fail "GenDyn 执行失败"
                exit 1
            }
        fi
        pass "GenDyn 完成"

        # 清理临时文件
        rm -f "$header"

        echo ""
        echo "===== 完成 ====="
        echo "动态库:     ${dylib}"
        echo "VML 封装:   Lib/dynamic/${libname}.vml"
        echo "各语言 FFI: Lib/<lang>/ext/lib${libname}.<ext>"
        echo ""
        echo "下一步:"
        echo "  1. 将 ${dylib} 放入 Lib/dynamic/"
        echo "  2. 在 VML 程序中: .linked  \"Lib/dynamic/${libname}.vml\""

    # 情况2: 输入是 .h 文件 + 已有动态库 → 直接 GenDyn
    elif [ "$ext" = "h" ]; then
        if [ -z "$dylib_path" ]; then
            fail "头文件模式需要指定动态库路径: -l <lib.dylib>"
            exit 1
        fi
        [ ! -f "$dylib_path" ] && { fail "动态库不存在: $dylib_path"; exit 1; }

        info "调用 GenDyn v2 (头文件模式)..."
        if $lang_only; then
            $IMPORT_DYNAMIC -g -n "$libname" -H "$infile" -r "$PROJECT_ROOT" 2>&1 || {
                fail "GenDyn 执行失败"
                exit 1
            }
        else
            $IMPORT_DYNAMIC -A -n "$libname" -H "$infile" -r "$PROJECT_ROOT" 2>&1 || {
                fail "GenDyn 执行失败"
                exit 1
            }
        fi
        pass "GenDyn 完成"

        echo ""
        echo "===== 完成 ====="
        echo "各语言 FFI: Lib/<lang>/ext/lib${libname}.<ext>"
    else
        fail "不支持的文件类型: .${ext} (需要 .c 或 .h)"
        exit 1
    fi
}

main "$@"
